import static io.restassured.RestAssured.given;

class PierwszyTestRestAssured {

    void sprawdzStatusOk() {
        given()
            .when()
                .get("http://localhost:8082/api/zadania")
            .then()
                .statusCode(200);
    }
}

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;

class TestPobraniaZadania {

    void pobranieZadaniaZwracaPoprawneDane() {
        given()
            .when()
                .get("http://localhost:8082/api/zadania/1")
            .then()
                .statusCode(200)
                .body("id", equalTo(1))
                .body("tytul", notNullValue());
    }
}

